insert into public.products (slug, title, updated, tagline, summary, image, sections, thin) values
('2c-3c-infusion-resin-systems', '2C 3C Infusion Resin Systems', '2025-12-23', 'Resin Infusion Systems', 'The Eldo-Mix newly developed metering system range for the processing of unfilled vacuum infusion resins combine highly accurate metering pumps with extremely fast control engineering. The Eldo-Mix vacuum infusion resin system has a mix ratio monitoring and regulating control package to insure contenuious and accurate metering ration accuracy of less than 1% deviation and the output rate during production can be modified in 2% steps.', '{"src":"/products/vacuum-infusion-molding.jpg","alt":"Resign Infusion system"}'::jsonb, null, true),
('2c-gel-coat', '2C Gel Coat', '2025-12-23', null, 'The ELDO-MIX gel coat systems have been especiallydeveloped for processing highly thixotropic materials onto the untreated surfaces of rotor blades. By the use of gearmetering pumps\ which are also suitable for abrasive fillersand magnetically coupled axial piston pumps for the Bcomponent; output rates of up to 5 l/min can be achieved. The material supply of the mobile system is carried out frommaterial pressure vessels that are installed on the chassis. Not only can materials with viscosities up to the flow limit beapplied with this gel coat system, but also the mixing ratiosare adjustable within a wide range.', '{"src":"/products/Gel_Coat-2C.jpg","alt":"Eldo mix on portable dolly"}'::jsonb, null, true),
('2c-infusion-resin', '2C Infusion Resin', '2025-12-23', null, 'The Eldo-Mix metering system range for the processing of unfilled vacuum infusion resins combine highly accurate metering pumps with extremely fast control engineering. The Eldo-Mix vacuum infusion resin system has a mix ratio monitoring and regulating control package to insure continuous and accurate metering ration accuracy of less than 1% deviation and the output rate during production can be modified in 2% steps', '{"src":"/products/vacuum-infusion-molding.jpg","alt":"Resign Infusion system"}'::jsonb, null, true),
('3c-glue-resins', '3C Glue Resins', '2025-12-23', null, 'The ELDO-MIX Glue Resin series metering \ mixing and dispensing system was designed to process the extremely high viscosity resins required to bond two composite components together', '{"src":"/products/vacuum-infusion-molding.jpg","alt":"Resign Infusion system"}'::jsonb, null, true),
('air-operated-diaphragm-pumps', 'Air Operated Diaphragm Pumps', '2025-12-20', 'Efficient, Versatile, Reliable', 'An efficient supply of Cold Adhesives / Glues / Slurries / Sludges Low-pressure diaphragm pumps are a type of positive displacement pump that utilizes a flexible diaphragm to move fluids. They are commonly used in various industries for applications such as chemical dosing, fluid transfer, and hydraulic systems. Here''s some detailed information about low-pressure diaphragm pumps:', '{"src":"/products/Zip-Series-Diaphragm-Pumps.jpg","alt":"Air operated Diaphragm pump for industrial applications"}'::jsonb, '[{"heading":"ZIP Series Diaphragm Pumps","paragraphs":["The ZIP Series is ideal for low-to-medium pressure transfer of single-component adhesives, sealants, and slurries. Known for versatility and reliability, these pumps are suitable for supply, circulation, and general industrial transfer applications."]},{"heading":"Key Features:","items":["Pneumatic, air-operated diaphragm design","Handles a wide range of viscosities and chemistries","Self-priming and dry-run capable","Minimal maintenance with robust, durable construction","Flexible port sizes for easy integration into existing systems","Suitable for drum, tote, or bulk supply"]},{"heading":"ZIP Finishing Pump Models","paragraphs":["Optimized for finishing operations, ZIP Finishing pumps deliver consistent flow and precise material control, ensuring uniform bead formation and repeatable dispensing results."]},{"heading":"Key Features:","items":["Precise air-operated diaphragm control for consistent output","Designed for finishing or coating applications","Supports intermittent and continuous dispensing","Resistant to wear from abrasive or heavy materials","Compact footprint for easy integration in production lines"]},{"heading":"Unica 4‑270 Diaphragm Pump","paragraphs":["The Unica 4‑270 is a robust industrial diaphragm pump designed for smooth material transfer of adhesives, sealants, and similar fluids, minimizing shear and maintaining material integrity."],"images":[{"src":"/products/wagner11_512c22ea-8634-4c6b-8c12-6765d8faf25c_612x.webp"}]},{"heading":"Key Features:","items":["Handles medium to high-viscosity materials","Pulsation-free flow for consistent dispensing","Durable components for long service life","Easy to disassemble and maintain","Ideal for both manual and automated transfer systems"]},{"heading":"Double Diaphragm Drum & Bulk Supply Pumps","paragraphs":["These pumps are engineered for drum and bulk material transfer, offering reliable operation and adaptability to various container sizes and material types."]},{"heading":"Key Features:","items":["Suitable for aluminum, stainless steel, polypropylene, or acetal construction","Handles a wide range of viscosities and chemistries","Designed for safe and efficient drum unloading","Self-priming and minimal pulsation for smooth material delivery","Compatible with metering valves and automated feed systems"]},{"heading":"Heavy-Duty Material Transfer Pumps","paragraphs":["For high-flow or abrasive materials, heavy-duty diaphragm pumps provide rugged, reliable performance for demanding industrial applications."]},{"heading":"Key Features:","items":["High flow rates for bulk material transfer","Durable, wear-resistant components","Self-priming and dry-run capable","Minimal maintenance requirements","Pulseless operation ensures smooth material delivery","Suitable for adhesives, slurries, coatings, and lubricants"]}]'::jsonb, false),
('alfamix', 'ALFAMIX', '2025-12-10', 'Polyurethane Processing Equipment', 'High Pressure foaming machines Alfamix Series productions of low and medium volumes single mixing head provision production for thermal insulation (panels, refrigerators, and packaging) production of flexible foam for furniture productions where it is necessary to replace low pressure foaming machines at a competitive price', '{"src":"/products/ALFAMIX.jpg","alt":"Alfamix on white background"}'::jsonb, null, true),
('cartridge-metering-valve', 'Cartridge Metering Valve', '2025-12-11', 'Metering Valves for Single Component Systems', 'The Cartridge Chamber Metering Valve is a new generation of precision metering valves based on a completely new principle. Example: Postive Displacement Cartridge Metering Valve. The metering chamber is an exchangeable cartridge contained within an aluminum valve body. The valve consists of two separate parts, a fluid section and a pneumatic section. This separation reduces the chance for leaking material to flow into the actuating air cylinder that might cause a malfunction of the valve. The needle is sealed by means of adjustable packing set. Speed of metering depends on the material viscosity and the material pressure.', '{"src":"/products/418-valve2nsfa2.jpg","alt":"Cartridge metering valve on white background"}'::jsonb, '[{"heading":"Cartridge Chamber Metering Valve Features and Benefits","items":["Valve Body Made Of Aluminum","Capable Of Withstanding High Pressure","Snuff Back Suction","Electric Or Pneumatic Activation Control","Option - Fine Tuning Of Shot Size","Option - Double Sensor Receptacles For Monitoring The Stroke Needle Position","Option - Handle With Pneumatic Or Electric Control"],"images":[{"src":"/products/Metering_Valves_Application.jpg"}]}]'::jsonb, false),
('chamber-metering-valve', 'Chamber Metering Valve', '2025-12-11', 'Chamber Metering Valves', 'Kirkco uses Chamber metering valves for processing low to high-viscosity media. Example: Positive Displacement Chamber Metering Valve. The valve consists of two separate parts. A control valve section and a metering chamber section. This separation means that it is possible to change or repair the metering range of the valve without having to remove the unit from the production line. The control valve functions as both the supply inlet and dispensing outlet. The metering chamber is used to set the metering volume. The metering volume is fully adjustable within the chamber’s given range. Standard sizes in different optional types allow a shot size from 0,050 up to 100,00 cm3', '{"src":"/products/415-valveimsfa2.jpg","alt":"Chamber metering valve"}'::jsonb, '[{"heading":"Cartridge Chamber Metering Valve Features and Benefits","items":["Variable discharge rate from 0.002 ml","Output rate of 0.1 to 45 ml/min","Speed of 0 to 150 rev/min","Maximum input pressure of 6 bar","Maximum operating pressure of 10 bar","Ideally suitable for all viscosities from highly fluid to pasty","Snuff-back function","Option - Cartridge supply 10cc / 30cc / 55cc","Option - Pressure regulator and level control for cartridge supply","Option - Spray adaptor","Option - Servo controller","Option - Various needle tips"]}]'::jsonb, false),
('conti-flow-compact', 'Conti-Flow Compact', '2025-12-23', null, 'Compact and slim design with a small footprint for narrow workspaces. Manual applications, Ergonomic integration of the control panel.', '{"src":"/products/conti-flow-compact.jpg","alt":"Conti-Flow Compact"}'::jsonb, null, true),
('conti-flow-lab', 'Conti-Flow Lab', '2025-12-22', 'Meter Mixing Unit for R&D and Prototype Applications', null, '{"src":"/products/csm_Conti-Flow-Lab_9438983ada.png","alt":"Conti-Flow Lab"}'::jsonb, '[{"paragraphs":["Conti-Flow Lab Benefits"],"items":["Servo driven precision gear pumps","PLC control","Intuitive operator panel for easy programming","Inlet / Outlet pressure control","Pot life control","Robust 2K processing equipment for reliable operation in demanding R&D production environments","Smart metering control","Proven Precision"]}]'::jsonb, false),
('conti-flow-vario', 'Conti-Flow Vario', '2025-12-23', 'Compact & Variable Two Component Epoxy Metering System', 'A compact and variable table-top unit for manual or automatic production processes. Proven Precision Servo-driven precision gear pumps provided the highest precision metering with low to medium-viscosity materials. Variable metering programs for optimized processes, including inlet and outlet pressure control.', '{"src":"/products/CF-vario-new-1.jpg","alt":"Conti flow vario for industrial dispensing automation applications"}'::jsonb, '[{"heading":"Comprehensive Process Control:","items":["Intuitive Operation","Mold Pressure Control (MPC) Option For Various Composite Processes for Composite-Processing: Infusion, RTM, RIM","Configurable with Different Feeding Units, tanks, pails, drums, or totes.","Re-Circulation","Agitation","8 Channel Temperature Control"]},{"heading":"Mixing:","items":["Gamma Mix Handgun","Static Emotionmix","Dynamic / Static"]},{"heading":"Application","items":["Integration Into Automation System","Bonding","Sealing","Casting","Encapsulation"]},{"heading":"Conti-Flow Vario Benefits","items":["Robust 1K and 2K processing equipment for reliable operation in demanding production environments","Smart metering control","Proven Precision","Comprehensive Process Control Possibilities","Mold-Pressure-Control (MPC) Option","Integration Into Manual or Automation System","Configurable with many useful options"]}]'::jsonb, false),
('conti-flow-versa', 'Conti-Flow Versa', '2025-12-23', 'Versatile & Flexible For Demanding Adhesive Meter Mixing Applications', 'Mobile and compact meter mix system for liquid to high-viscous 2-component materials. This metering platform was developed to pump, proportion, mix, and dispense various two component sealants and adhesives. Typical materials this product is used for include: polysulfide, epoxy, silicone, and polyurethane materials for auto, truck/bus, window, and aircraft industries. Pumps move the fluid components from their respective containers on ratio eliminating an intermediate, variable or fixed ratio, proportioner. The Conti Flow Versa series proportioner synchronizes the volume of the two components through two precisely sized positive displacement gear pumps. Pumps are coated with protective material to prevent ware due to fillers. The fluids are delivered through hoses to a mixer assembly.', '{"src":"/products/csm_Conti-Flow-Versa_59010974af.png","alt":"Conti-Flow Versa"}'::jsonb, '[{"paragraphs":["Selecting from standard pump availability determines the ratio range of the machine. A programmable electronic control allows for an adjustable variable ratio within a given range. With the optional ratio monitoring package, the computer will self-adjust automatically."]},{"heading":"Conti-Flow Versa Benefits:","paragraphs":["The Gear Pump Two-component meter mix machines are designed for the efficient application of pasty / liquid synthetic reactive resin materials such as adhesives, polyurethanes, epoxies and silicones and is ideal for use in medium to large production runs.","Machine is used for bonding and sealing applications involving highly reactive materials in IG, molding, potting and encapsulation, foam filling of hollow spaces as well as for glazing."],"items":["Robust 1K and 2K processing equipment for reliable operation in demanding production environments","Smart metering control","Proven Precision","Comprehensive Process Control Possibilities","Mold-Pressure-Control (MPC) Option","Integration Into Manual or Automation System","Configurable with many useful options","Versatile & flexible for demanding workspaces","High metering accuracy due to short distance from metering to dispensing","Highly comfortable operation with flexible boom and balancer support","Different options & features are configurable to meet requirements"]}]'::jsonb, false),
('conti-pro', 'Conti-Pro', '2025-12-10', 'Metering and Mixing System for encapsulation applications', 'Compact 2-component, servo driven Progressive Cavity metering unit suitable for processing the smallest metering volume in precision applications requiring the necessity of processing abrasive or shear-sensitive materials at the highest accuracy. For Low- to medium viscous materials with functional fillers. Compact and lightweight, ideal for robot mounting for high accuracy of the smallest volumes.', '{"src":"/products/csm_ContiPro_f1c929a713.png","alt":"Conti Pro injection dispensing"}'::jsonb, '[{"heading":"Conti-Pro Benefits","items":["Robust 1K and 2K processing equipment for reliable operation in demanding production environments","Smart metering control","Zero-backlash screw & servo drive","Compact & low weight","Robust design"]},{"heading":"PCP Metering ValvePrecise - Variable - High Repeat Accuracy - Clean","paragraphs":["The PCP Metering Valve is based on the volumetric principle of an endless (eccentric) piston, whereas the core components, rotor and stator, form a perfectly sealed metering chamber. The eccentric movement of the rotor allows for a low-shear motion of the medium from one chamber to the next chamber without compressing the media. The metering chamber is optimally designed for dispensing liquids and pastes containing fillers.","By combining the principle of the eccentric screw pump with precision control of the metering time and rotor speed, the new PCP Metering / Dosing Valves support the proportional volume to speed metering application of various lubricants/adhesives/epoxies / thermal paste in quantities with the highest precision and repeatable accuracy.","Since the motor controller can also turn the rotor backward, these PCP Metering / Dosing Valves guarantee clean metering without dripping. Precise, reliable, and consistent volumetric metering is possible thanks to the adjustable application speed and rotor rotation."]},{"heading":"For Perfect Metering and Dosing Applications:","paragraphs":["PCP Metering Valves have been designed for precise metering/dosing of fluids and pastes and are especially suitable for abrasive media and for Metering/Dosing and dispensing proportional to speed. Accuracy and repeatability is ± 1%."]},{"heading":"Advantages:","items":["Suitable for variable metering of low to high-viscosity and abrasive materials.","Pressure resistant up to 35 bar - the rotor and stator form a metering chamber with optimum seal","Integrated control unit and release button for manual operation","Adjustable application speed thanks to variable speed drive.","Metering volume proportionate to rotation speed","High metering and repeat accuracy","Broad range of applications (robotics, servo technology and manual workstations/assembly stations)","Point and bead application","Flexible metering volume - continuously variable metering quantity","No dripping (snuff-back)","Pulsation-free"]},{"heading":"Industries","items":["Aerospace","Automotive","Electronics","Cosmetics","Pharmaceutical","Medical technology"]},{"heading":"Typical Applications","items":["Metering / Dosing of Filling Compounds","Coating of Electronic Components","Protective Coating of Printed Circuit Boards","Application of Epoxy Resin Adhesives","Bead Dispensing","Sealing","Metering and Dosing","Filling"]}]'::jsonb, false),
('diaphragm-dispensing-valve', 'Diaphragm Dispensing Valve', '2026-05-14', 'Clever solutions to the greatest challenges', 'The advantage of diaphragm dispensing valves is their ability to process material with challenging properties in continuous shot applications. The valves are designed for care-free dispensing of low- to high-viscosity, filled or unfilled, abrasive or chemically reactive single-component (1K) fluids. Part of their structure is an integrated diaphragm that separates the pneumatic and the metering parts of the valve. As a result, only the valve head and the diaphragm come in contact with the material, while the material passageway can be easily flushed if necessary. The size of the orifice is regulated by stroke adjustment. The snuff-back mechanism effectively prevents material from dripping after shot completion. This valve is exceptionally easy to maintain.', '{"src":"/products/Diaphragm_Dispensing_Valve_03_24_2026.jpg","alt":"Diaphragm Dispensing Valve"}'::jsonb, '[{"heading":"Diaphragm Dispensing Valve Features and Options","items":["Continuous Application (Time-Pressure Dispensing)","Internal diameter 2, 4 and 8 mm","Max. Input Pressure 160 Bar","Snuff-back effect","Option - Solenoid Valve Plate 24 V","Option - Various Adapters And Needle Tips","Option - Pneumatic Or Electric Handle","Option - Heated valve with or without plug 230 V AC / 200W"]}]'::jsonb, false),
('dosing-inspection-system', 'Dosing Inspection System', '2026-05-13', 'Intelligent monitoring of Impulse Dosing Valve processes: automatic, verifiable, and in real-time.', 'Reproducible quality poses the greatest challenge in industrial lubricant dosing. Impurities or air inclusions in the lubricant can disrupt the dosing process, resulting in poor outcomes. The innovative DIS Dosing Inspection System by SOMA offers automatic and reliable detection of subpar dosing results, enabling prompt corrective actions. Benefits of a Dosing Inspection System condensed 100% real-time monitoring of dosing impulses on the SOMA IDV Impulse Dosing Valve. Utilizes patented process monitoring via a piezo pressure sensor on the nozzle output. Configurable through a web interface for digital I/O signal to higher-level control units. Automatic determination of position in the process using teach mode.', '{"src":"/products/img-impulse-dosing-valve1.jpg","alt":"Dosing Inspection System"}'::jsonb, null, true),
('double-ram-pump', 'Double Ram Pump', '2026-02-26', 'High Performance Piston Pumps', 'This drum pump model is available exclusively as a double- acting chop check pump. Along with greases and oils, it also processes adhesives, sealants, polyurethanes, or silicones with viscosities of up to 5.0 million mPas. Material is pressure fed directly from the original containers. The piston pump is ideal for individual station material supply, and it serves equally well as a central material supply system. The pumps in this range are modular, robust, economical, extremely dependable, and easy to maintain and service.', '{"src":"/products/piston-pump-drum-pump.jpg","alt":"piston-pump-drum-pump"}'::jsonb, '[{"heading":"Ram Pump / Double Ram Pump Features","items":["Supply of medium to high viscosity material","Flow rate up to 6 litres/minute at 20 double strokes","Pressure ratio up to 75:1","Max. viscosity 5 million mPas","Differential piston pumps with fast-switching air motors","1- or 2-hand operation","Modular design with configurable components","Sealing available in various sizes and material finishes"]},{"heading":"Tandem pumps","paragraphs":["Many applications require an uninterrupted material feed maintained at all times. For such cases, all KIRKCO pump models are available as a tandem version.","Tandem pumps feature an automatic mechanism that switches between the pumps whenever material level is low, so that container change can proceed without interruption and time pressure. With clean handling and minimal material residue left in the drum, KIRKCO pumps have earned their place in the most efficient production lines around the world. All sizes are available as tandem versions. Transfer pumps for direct supply from original containers Depending on the application type, it may be useful to be able to supply material directly from the original containers using a transfer pump. KIRKCO transfer pumps are double acting pumps with a fast-switching air motor. It should be noted that the use of transfer pumps is always dependent on the material properties and the container type."],"images":[{"src":"/products/piston-pump-tandem-pump.jpg"}]},{"heading":"Key Features:","items":["Low viscosity material feeding via the bung hole","Flow rate up to 1.0/6.0 litres/minute at 20 double strokes","Pressure ratio up to 21:1/36:1","Max. viscosity 80,000 mPas","Sealing available in various sizes and material finishes"],"images":[{"src":"/products/Tandem-Pump_AXFP-M_3457.jpg"}]}]'::jsonb, false),
('drum-pumps-for-lubricants', 'Drum Pumps For Lubricants', '2026-05-24', 'Reliable Drum Pump Solutions for Grease, Oil & Lubricant Feeding', 'Kirkco’s drum pumps for lubricants are engineered to reliably transfer low- to medium-viscosity greases and oils directly from their original containers, eliminating air pockets and material separation. These robust drum pump systems support both centralized and individual feed applications, making them ideal for supplying lubricant to metering valves, pump stations, or lubrication points in industrial settings.', '{"src":"/products/DrumPUmp_200Lt.jpg","alt":"Drum Pumps For Lubricants"}'::jsonb, '[{"heading":"How They’re Used","items":["Automated lubrication systems requiring steady supply to metering valves","Machine tool lubrication stations","Assembly lines and conveyors with continuous grease/oil demands","Centralized or localized lubricant feed systems in heavy machinery environments"]},{"heading":"Key Benefits:","items":["Uninterrupted feed during drum changeovers.","Reduces process downtime and maintenance intervention.","Ideal for assembly lines or high-cycle lubrication needs."]},{"heading":"Standard Drum Pump Features","paragraphs":["These engineered features make Kirkco drum pumps ideal for feeding metering valves or lubrication points in assembly lines, machining centers, and automated lubrication systems."],"items":["High delivery rate for efficient lubricant transfer.","Complete container emptying to minimize waste and reduce costs.","Expandable modular design with options like mixers, filters, and monitoring ports.","Pressure release integration to reduce residual pressure and prevent material separation.","Automatic drum changeover (tandem versions) for continuous supply without interruption.","Manual 1- or 2-hand safety operation available where needed."]}]'::jsonb, false),
('dyna-static', 'Dyna Static', '2025-12-10', null, 'Difficult to mix materials, use Dynamic Static Mixers. The dynamic static mixers are a combination of a dispensing valve and a drive motor. The motor rotates the mixer element in the plastic tube. The drive is either pneumatic or electric. Static-dynamic mixers run without flushing agents because the components are supplied to the mixer tube intake separately Mixing of the two components shall be done with a dynamic static mixer. This unit is specifically designed for materials where additional shear needs to be introduced to ensure thorough mixing. The two components remain separate until entering the mixer. Only then does homogeneous mixing of the two components take place. The mixer is fastened to the gun and remains stationary. As the material is dispensed, the mixing element inside the mixer rotates at a high speed, thoroughly mixing and blending the materials. (Solvent/material purge optional but not required with disposable mixers)', null, '[{"heading":"Dynamic Mix 3.0","paragraphs":["Dynamic mix 3.0 / Dynamic mixer with disposable mixing chamber and two component swivel joint for integration into manual glass sealing applications. PERFECT MATCH WITH ECOSTAR EVO.","Optionally available as integrated in Ecostar evo-series or as retro-fit kit for existing installations"]},{"heading":"Benefits","items":["Freezer or solvent flushing pump no longer required","No more loss of material through purging processes","Saving of costs for disposal of waste material","No more necessity for cleaning of Z-swivel joint","No purchase of trumpet mixer required","Less attrition of the plant by lowering the pressure level to approximately 120 bar"]},{"heading":"Dynamic Mix 6.0","paragraphs":["Dynamic Mix 6.0 / The Dynamic Mix 6.0 combines the technical advantages of a dynamic mixer with the economical benefits of a static mixer. The Dynamic Mix 6.0 requires a controller. Depending on version the mixer will be integrated in parent control or it comes with a retrofit integration kit."]},{"heading":"Benefits","items":["Elimination of purging adhesive losses","Minimize cost of waste e material","Saving of costs for disposal of waste material"]}]'::jsonb, false),
('dynamic-static-mixers', 'Dynamic Static Mixers', '2025-12-10', null, 'The most difficult to mix materials use true Dynamic Mixers. Dynamic mixers can mix materials with an extremely short pot life, widely differing viscosities and mixing ratios. The mixing rotor in the central chamber mixes the components evenly within a very short time. The mixer head can be operated either cooled or heated. The mixer motor drives are either pneumatic or electric. Welcome to the forefront of metering and mixing technology – your ultimate partner in the precise processing and application of single and multi-component adhesives and sealants. Our cutting-edge eMotionMix system offers a comprehensive solution, seamlessly integrating dynamic mixing heads, automation, and materials for unparalleled perfection and reliability.', '{"src":"/products/Picture1.png","alt":"Dynamic static mixer dispensing valve"}'::jsonb, '[{"heading":"eMotionMix: A One-stop Solution","paragraphs":["Discover your technological advantage with eMotionMix – where perfection and reliability meet innovation in metering and mixing technology.","From foaming and bonding to sealing, potting, and automation, eMotionMix stands as the pinnacle of innovation in metering and mixing technology. The dynamic mixing head, boasting revolutionary valve technology, is engineered for the efficient mixing of low to high-viscosity polymeric reaction substances."]},{"heading":"Key Features:","items":["Compact Design: Lightweight and small, our mixing head is designed for convenience.","Precision Metering: Achieve metering accuracy with a deviation of less than 1%, dependent on material, discharge capacity, and mixing ratio.","Easy Installation: Simplified installation and removal of mixing systems (mixer and mixing chamber).","Drip-free Operation: No dripping of mixed components ensures clean and efficient processes.","User-friendly Maintenance: Streamlined cleaning and maintenance procedures for the mixing head and systems","Optimal Overlapping: Perfect bead overlapping at the start and end, with the right materials.","Low Wear: Experience minimal wear, ensuring durability and longevity.","Recirculation System: Recirculation of all components to the mixing system for enhanced efficiency."]},{"heading":"Technological Advantages","paragraphs":["Our innovative dynamic mixing head offers a range of technological advantages, setting new standards in the industry:"],"items":["Highly Dynamic Mixing: Achieve highly dynamic mixing, even with extreme mixing ratios and significant differences in viscosity.","Guaranteed Reactivity: Dynamic mixing technology ensures guaranteed reactivity when handling low to high-viscosity polymeric reaction substances.","Compact Design: The mixing head''s unique valve design results in an extremely compact structure.","Low Maintenance: Benefit from low-maintenance system technology, reducing downtime and operational costs.","Global Availability: Enjoy the convenience of web-based control technology for real-time maintenance and training, globally accessible."]},{"heading":"Comprehensive System Solutions","paragraphs":["Our commitment extends beyond innovative products. We offer comprehensive system solutions worldwide, including:"],"items":["Optimal Processing: Ensure optimal processing of sealing foams, adhesives, and potting compounds.","Automated Application: Achieve automated application of adhesives and sealants, even on three-dimensional components, grooves, and molds.","Intelligent Automation: Embrace intelligent automation with state-of-the-art control technology","Process and Material Consulting: Benefit from our expertise with process consulting, optimization, and material consulting and selection, independent of supplier and material type."]}]'::jsonb, false),
('eco-mix', 'ECO MIX', '2025-12-26', 'Polyurethane Processing Equipment', 'The strong international focus that has been placed on greenhouse gases and gases which are hostile to the ozone layer, has led ISC to deep and strong efforts for the development of efficient and environmentally friendly foaming processes. Today, ISC puts a lot of efforts to helping customers in shifting their equipment for hydrocarbons-blown foams all over the world, with a wide range of available metering systems dedicated to this process. The blending unit “Ecomix” is an innovative, simple, and precise mixing system that allows the use of new generation blowing agents, including hydrocarbons, only when necessary. Combined with other complementary equipment it helps to optimize times and methods in the production process.', '{"src":"/products/ECO-MIX.jpg","alt":"Eco mix dispensing with spray booth attachment"}'::jsonb, '[{"heading":"Equipment Packages","items":["High efficiency dosing pump for pure Polyol, coupled to a motor at variable speed by means of frequency converter.","Safety pressure gauge at Polyol dosing pump feeding.","Safety pressure gauge in suction to the HC blowing agent metering pump.","HC blowing agent metering pump diaphragm type coupled to a frequency converter-driven motor for ratios/deliveries setting and change.","Safety pressure gauge at the HC blowing agent metering pump feeding point.","Static mixer to get a homogenous blend.","Polyol flow control made of volumetric flowmeter.","Flowmeter for HC blowing agent with high accuracy.","Automatic valves for recycle pressure adjustment on Polyol and HC blowing agent line.","Pressure balance system to ensure a perfect blending.","Continuous monitoring of the blend via analog PLC control.","PLC Siemens S7-1200 series for data processing.","HMI type Siemens KTP 700 series for settings and alarm visualization.","Frequency converter for POLYOL and HC Blowing agent pump motors.","Ethernet connection for production data facility"]}]'::jsonb, false),
('econo-mix', 'Econo-Mix', '2025-12-07', 'DOPAG ECONO-MIX® piston type metering and mixing system', 'Econo-Mix Metering and Mixing System for low to medium viscosity two-component reactive materials. We characterize the ECONO-MIX by its simplicity in function and design, friendliness of operation, and ease of maintenance. This system is a competitive starter model in two-component metering and mixing technology. This system is capable of processing most reactive polymers, like polyurethanes, silicones, and epoxy resins. They can be unfilled, filled as well, or slightly abrasive. The ECONO-MIX unit is a dependable and reliable two-component metering and mixing proportioning system that is best used for small to medium production applications. Customization of the base system is available as necessary for the specific application. The ECONO-MIX is a solvent-free, positive displacement piston pump type metering and mixing system, used to handle low to medium viscosity multi-component media such as epoxy resins, polyurethanes, or silicones with a volumetric mixing ratio of between 1:1 and 6.25:1.', '{"src":"/products/ECONO-MIX2.jpg","alt":"Econo-Mix Industrial application dispensing"}'::jsonb, '[{"paragraphs":["Low-pressure feed systems, such as diaphragm pumps or pressure vessels, are used to supply the material into the positive displacement piston metering pumps. Pressure tanks can be mounted onto the machine chassis, or a remote bulk feed unit is available for feeding directly from 55-gallon drums.","The pumps are driven by a single air motor. A lever system connects the pumps and the drive. The pump for the A component is fixed to the lever system and shares the same stroke length as the drive motor. The pump for the B component is adjustable along a lever system providing a variable stroke length, which is used for the fine adjustment of the mixing ratio.","The ECONO-MIX is typically fitted with our standard two-component static mixing system that includes a twin snuffer valve combined with a disposable static mixer. The valve contains an infinitely adjustable “snuff back” effect to avoid dripping after metering has finished. Should mixed material be allowed to cure in the mixer, it can be replaced simply and inexpensively, thus avoiding a time-consuming, expensive, and environmentally damaging solvent flushing cycle.","Optionally, we can offer both dynamic mixers and/or dynamic static mixer valves where the material requires an aggressive blending cycle necessary to achieve its proper mix."]},{"heading":"Standard:","items":["Portable chassis","Pressure vessels","Double-acting piston pumps","Air motor with lever system","Static mixing system","Twin snuffer valve","Disposable static mixer","Pneumatic-mechanical control"]},{"heading":"Optional:","items":["Static-dynamic mixing systems","Mixing block with static steel mixer","Pressure vessels in variable sizes","Level control","Agitator (electric or pneumatic)","Heating","Flushing","Pot life control","Material filter","Material pressure regulator","Degassing / Vacuum System"]},{"heading":"Typical Applications:","items":["Coating","Gluing / Bonding","Rapid Prototyping","Encapsulating","Potting"]},{"heading":"Features and Benefits:","items":["Compact Design: Easy-to-handle system with continuous output","Economic Solution: A low-cost continuous metering system as an alternative to hand mixing","Variable Mix Ratio: Pneumatic motor with beam-supported pump linkage system","Variable Output Rate: Continuous flow rate pneumatically adjusted","Solvent-free Standards: Solvent flush available as necessary","Manual Operation: Particularly suitable when small quantities are required","Standard Version: Various options available for customization","Various Mix Systems: Static, dynamic, static/dynamic","Bulk Supply/Tanks: Several sizes of pressure vessels"]}]'::jsonb, false),
('ecostar-evo', 'Ecostar EVO', '2026-02-26', 'Metering and mixing plant for manual industrial applications', 'The new Ecostar EVO series of manual two-component metering and mixing plants provides a set of new features and improvements while still coming with the proven and reliable core components of the well-known Ecostar line. The new boom features a higher flexibility in the workspace, optionally by enabling movements in two planes. The new mixing unit requires less maintenance or cleaning. Moreover, maintenance of the mixing unit is even easier now as the boom can be lowered easily. The floor space requirement of the Ecostar EVO has been significantly reduced, which makes it one of the most compact designs in the market. The new Ecostar EVO helps to reduce the overall manufacturing cost by increasing work efficiency through compactness, enhanced popularity with workers as well as reduced maintenance and space requirements.', '{"src":"/products/csm_Ecostar_PD_a609ba0d3d.png","alt":"Ecostar Evo Industrial application dispensing"}'::jsonb, '[{"heading":"Ecostar-EVO Standard Features","items":["Adjustable mixing ratios","Optimal platen design for lowest drum residues","Proven RT pump sealing system for minimum maintenance","Encapsulated design for higher operator safety and lowest noise","Flexible Boom design, optionally with new manipulator","New Alpha Mix, optimized for easy cleaning and maintenance","200L drum garage for ergonomic exchange","Drum low/empty warnings for A&B component","Pot life and mixer service life are adjustable"]},{"heading":"Ecostar-EVOClass","paragraphs":["Hydraulic Pump Drive for most common applications"]},{"heading":"Ecostar-EVOAir","paragraphs":["Pneumatic Drive Motor for reduced output requirements"]},{"heading":"Ecostar-EVOAir 20","paragraphs":["Pneumatic Drive Motor for reduced output 20L pail feeder for Components A and B"]},{"heading":"Ecostar-EVOMax","paragraphs":["For maximum output requirements"]},{"heading":"Ecostar-EVOPlus","paragraphs":["For the processing of the additional booster/accelerator materials.","Get a Quote For Ecostar-EVOPlus Hydraulic Pump Drive for most common applications","Get a Quote For Ecostar-EVOClass Pneumatic Drive Motor for reduced output requirements","Get a Quote For Ecostar-EVOAir Pneumatic Drive Motor for reduced output 20L pail feeder for Components A and B","Get a Quote For Ecostar-EVOAir 20 For maximum output requirements","Get a Quote For Ecostar-EVOMax For the processing of the additional booster/accelerator materials."]},{"heading":"Ecostar Optional Equipment:","paragraphs":["Ecostar Parts & Accessories (PDF Download)"],"items":["Manipulator for comfortable operation","Heated version for component A","Cartridge filler device","200L Drum feeder for component B","Various boom and hose extensions","Rinsing pump for cleaning solvent","Freezer"]}]'::jsonb, false),
('eldo-mix', 'Eldo-Mix', '2025-12-23', 'Dopag Eldo-Mix® Mixing and Metering', 'ELDO-MIX multi-component metering systems can process all polymers such as polyurethanes, silicones and epoxy resins. The ELDO-MIX is an electrically driven positive displacement gear metering system that is suitable for non-filled, non-abrasive, low to medium viscosity media. A special version of gear pumps is available for processing filled material applications. The ELDO-MIX series can obtain a wide range of mixing ratios and includes models that process more than two components simultaneously. The material delivery can be dispensed in a continuous flow or metered in a measured shot. The metering ratio is variable and selected via the electric motor speed and the metering pump selection. A metering computer operates the system automatically and enables an extremely varied range of monitoring, control and documentation functions. All ELDO-MIX models can be expanded to suit your needs by means of optional accessories. The standard version runs without flushing agents. “SOLVENT FREE”', '{"src":"/products/eldo-mix-1z6mf82.jpg","alt":"Eldo-Mix"}'::jsonb, '[{"heading":"Eldo-Mix is Suitable For:","items":["Casting","Coating","Sealant application","Gluing"]},{"heading":"Eldo-Mix 101","paragraphs":["The ELDO-MIX 101 is a solvent free gear metering and mixing system used to handle low to medium viscosity multi component media such as epoxy resins polyurethanes or silicones with mixing ratios between 100:100 and 100:10.Special configurations to process high viscosity media are also available."]},{"heading":"Eldo-Mix 202","paragraphs":["The ELDO-MIX 202 is a table top, solvent free gear metering and mixing system used to handle low to medium viscosity multi component media such as epoxy resins polyurethanes or silicones with a volumetric mixing ratio of between 100:100 and 100:5.Special configurations to process high viscosity media are also available."]},{"heading":"Eldo-Mix 301, 302, 303","paragraphs":["The ELDO-MIX 300 series is a solvent free gear metering and mixing system used to handle low to medium viscosity multi component media such as epoxy resins polyurethanes or silicones with a volumetric mixing ratio of between 100:100 and 100:2.Special configurations to process high viscosity media are also available. This system can be customised for individual customer needs and integrated without difficulty into automation cells."]},{"heading":"Eldo-Mix 701, 702, 703","paragraphs":["The Eldo-Mix 700 series is a newly developed metering system range for the processing of unfilled vacuum infusion resins combine highly accurate metering pumps with extremely fast control engineering. The Eldo-Mix vacuum infusion resin system has a mix ratio monitoring and regulating control package to insure continuous and accurate metering ration accuracy of less than 1% deviation and the output rate during production can be modified in 2% steps.","Get a Quote For Eldo-Mix 700 Series The ELDO-MIX 101 is a solvent free gear metering and mixing system used to handle low to medium viscosity multi component media such as epoxy resins polyurethanes or silicones with mixing ratios between 100:100 and 100:10.Special configurations to process high viscosity media are also available.","Get a Quote For Eldo-Mix 101 The ELDO-MIX 202 is a table top, solvent free gear metering and mixing system used to handle low to medium viscosity multi component media such as epoxy resins polyurethanes or silicones with a volumetric mixing ratio of between 100:100 and 100:5.Special configurations to process high viscosity media are also available.","Get a Quote For Eldo-Mix 202 The ELDO-MIX 300 series is a solvent free gear metering and mixing system used to handle low to medium viscosity multi component media such as epoxy resins polyurethanes or silicones with a volumetric mixing ratio of between 100:100 and 100:2.Special configurations to process high viscosity media are also available. This system can be customised for individual customer needs and integrated without difficulty into automation cells.","Get a Quote For Eldo-Mix 300 Series The Eldo-Mix 700 series is a newly developed metering system range for the processing of unfilled vacuum infusion resins combine highly accurate metering pumps with extremely fast control engineering. The Eldo-Mix vacuum infusion resin system has a mix ratio monitoring and regulating control package to insure continuous and accurate metering ration accuracy of less than 1% deviation and the output rate during production can be modified in 2% steps.","Get a Quote For Eldo-Mix 700 Series"]}]'::jsonb, false),
('eldo-mix-401t-tooling-mix', 'Eldo-Mix 401T & Tooling Mix', '2025-12-22', null, 'The ELDO-MIX 401 T has been specifically designed for handling pasty two component media\including polyurethanes and epoxy resins\ as well as for successfully processing microball-filled materials.', '{"src":"/products/EM401T.jpg","alt":"Eldo mix and Tooling Mix on a red portable dolly"}'::jsonb, null, true),
('electronic-metering', 'Electronic Metering', '2025-12-26', 'Electronic Metering & Control Systems for Precision Lubrication Delivery', 'Electronic metering refers to the use of digital control units and sensors to manage, monitor, and automate lubrication metering processes — ensuring precise flow, repeatable delivery, and real-time verification across lubrication systems. These systems bridge pumps, metering valves, and monitoring devices to deliver reliable, data-driven lubrication control.', null, '[{"heading":"Key Features:","items":["Communication between system components and valves","Stores multiple preset metering programs","Interfaces with gear flow meters and light barriers","Works as a standalone metering controller or PLC interface"]},{"heading":"Benefits:","items":["Reduces setup time and operator dependency","Improves repeatability and system feedback","Enables advanced automation of lubrication cycles"]},{"heading":"Flow Meter Features:","items":["Adjustable pulse multiplication for high resolution","LED status indicators","Construction materials: cast iron, stainless steel, or aluminum","Compatible with various adaptors and heating options","Integrates with dispensing or metering valves for precise control"]},{"heading":"System Feedback & Verification","items":["Adjust delivery in closed-loop mode","Alert operators to anomalies","Log performance for quality or maintenance tracking","Optimize overall lubrication efficiency"]}]'::jsonb, false),
('fill-mix', 'Fill Mix', '2025-12-10', 'Polyurethane Equipment', 'The FILL MIX unit is a cutting-edge solution designed to seamlessly process solid fillers or shredded polyurethane scraps, transforming them into polyol for various applications. This versatile unit is becoming increasingly indispensable in the realm of polyurethane production for several compelling reasons: Enhanced Mechanical Features: By incorporating fibreglass into the manufacturing process, the FILL MIX unit significantly improves the mechanical properties of the final products. This results in parts with superior strength and durability. Flammability Reduction: The unit offers the capability to reduce the flammability coefficient of manufactured parts by introducing graphite flakes. This ensures that the final products meet stringent safety standards, making them suitable for a wide range of applications.', '{"src":"/products/Fill-Mix.png","alt":"Fill mix device with material container tank"}'::jsonb, '[{"heading":"Cost-Effective Polyol Usage","paragraphs":["In an era where cost efficiency is paramount, the FILL MIX unit enables manufacturers to reduce polyol consumption, thereby saving money. The addition of calcium carbonate achieves this cost reduction without compromising the quality and performance levels of the final products."]},{"heading":"Eco-Friendly Scrap Repurposing","paragraphs":["The unit goes a step further by addressing environmental concerns. It facilitates the reuse of milled scraps in the production process, mitigating disposal costs. Equipped with a shredder and a cochlea, Fillmix efficiently loads milled parts into its tank, promoting sustainable manufacturing practices.","The FILL MIX unit provides precise control over the percentage of load in polyol, ensuring a consistently blended mixture. This meticulously crafted blend is then readily available for automatic loading into the target foaming machine. The unit seamlessly integrates into any suitably equipped foaming machine, offering manufacturers the flexibility to enhance their production processes.","Embrace the future of polyurethane processing with FILL MIX, a reliable and innovative solution that caters to the evolving needs of the industry, delivering efficiency, cost savings, and environmental sustainability."]}]'::jsonb, false),
('flow-meters', 'Flow Meters', '2026-05-24', 'Precision Flow Meters for Accurate Lubricant Monitoring & Control', 'Flow meters are instruments designed to measure the volume or rate of fluid moving through a system — essential for verifying delivery, monitoring performance, and controlling lubricant usage in industrial lubrication and metering applications. They provide real-time feedback that helps ensure accurate flow rates, track material usage, and enable better process control across lubrication networks and automated dispense stations.', '{"src":"/products/megaflowmelter_CLEAN.jpg","alt":"Flow Meters"}'::jsonb, null, true),
('flow-regulating-valve', 'Flow Regulating Valve', '2025-12-24', 'Flow Regulating Valves for Steady Lubricant Flow and Consistent Delivery', 'A flow regulating valve is a mechanical device used to control the rate of lubricant flow through a system, independent of variations in pressure. Unlike pressure regulators (which stabilize pressure), flow regulating valves ensure that the amount of material moving through the line remains consistent — which is vital in lubrication and metering systems where repeatable delivery rates directly impact performance and equipment life.', null, '[{"heading":"Adjustable Flow Regulating Valve","paragraphs":["An adjustable flow regulating valve allows operators to set a desired flow rate that is maintained regardless of moderate pressure fluctuations. This adjustment mechanism provides flexibility across applications with differing lubrication demands."]},{"heading":"Key Features:","paragraphs":["Simple manual adjustment for flow setpoint","Stable flow output across operating conditions","Robust design compatible with greases and oils","Minimal maintenance with durable internals","Suitable for use upstream of metering valves or dispensing points"]},{"heading":"Benefits:","paragraphs":["Ensures consistent feed regardless of pressure variations","Reduces demand changes on downstream valves","Supports smoother lubrication cycles"]},{"heading":"Ideal For:","paragraphs":["Centralized lubrication systems","Feed lines to metering valves","Automated lubrication networks"]},{"heading":"Preset Flow Control Valve","paragraphs":["A preset flow control valve is factory-set to maintain a specific flow rate, reducing setup time and potential field adjustment errors. This configuration is ideal when lubrication systems require repeatable performance and minimal on-site calibration."]},{"heading":"Key Features:","paragraphs":["Factory preset flow rate for predictable performance","Eliminates the need for field adjustments","Compact, rugged valve body","Works with a variety of lubricant viscosities","Low-maintenance design"]},{"heading":"Benefits:","paragraphs":["Quick installation with consistent out-of-the-box performance","Reduces configuration errors","Steady flow rate for metering and dispensing"]},{"heading":"Ideal For:","paragraphs":["Production lines with standard flow requirements","Multi-point lubrication systems","Systems requiring quick deployment"]},{"heading":"Common Industrial Applications","paragraphs":["Flow regulating valves are widely used where steady, predictable lubricant delivery is critical, such as:","By stabilizing flow, these valves help maximize uptime, minimize material waste, and support predictable maintenance routines."],"items":["Centralized lubrication networks feeding multiple lubrication points","Automated manufacturing requiring consistent feed to metering valves","Machine tool lubrication with stable flow demands","Assembly lines with repeatable lubrication cycles"]},{"heading":"Why Choose Kirkco Flow Regulating Valves","paragraphs":["Kirkco flow regulating valves are engineered for:","When paired with flow meters, filters, and regulators, Kirkco’s flow regulating valves help you build a precise, controlled lubrication system that supports both manual and automated applications."],"items":["Flow accuracy and stability across pressure variations","Compatibility with greases, oils, and industrial fluids","Durable construction for long service life","Easy integration with lubrication supply and metering systems"]}]'::jsonb, false),
('frp-gel-coat-systems', 'FRP Gel Coat Systems', '2025-12-23', 'Industrial Gel Coat Equipment for Durable, Premium Composite Surfaces', 'FRP gel coat systems are designed to apply pigmented resin coatings onto composite molds prior to laminate build‑up, providing the cosmetic finish and surface protection of open‑mold composite parts. Gel coat resins are typically sprayed onto the mold at a controlled thickness and later overlaid with reinforcing materials to complete the composite structure.', '{"src":"/products/frp-gel-coat.jpg","alt":"Gel Coating on the interior of a marine application"}'::jsonb, null, true),
('gear-flow-meter', 'Gear Flow Meter', '2025-12-26', 'Precise monitoring and control of the metering process', 'The gear flow meter has been developed specifically for use in metering and mixing systems. In processes involving one-part media such as greases, oils and adhesives, it is used for measuring the exact material flow rate at any given moment. The measuring principle is based on the volumetric gear displacement system, characteristic for its accuracy and compressive strength. The measuring element comprises of a very precisely fitted pair of gears placed in the housing ofthe flow meter. The rotation of the measuring element is detected by a contactless sensor system and converted into digital signals. A metering unit containing a gearbased flow meter combined with a flow-regulating and dispensing valve is ideal for an accurate dispensing or filling of larger quantities of fluids.', '{"src":"/products/electronically-Flow-Meter-Exp1bnv92.gif","alt":"Flow Meter Expanded to see inside the device"}'::jsonb, '[{"heading":"Features","items":["Monitoring and control of metering processes","Adjustable pulse multiplication up to factor 128 for high measuring resolutions","Status LED","Tooth volume 0.04 / 0.1 / 0.2 / 0.4 / 1 / 2 cm","Cast iron, stainless steel or aluminum design","Plain or ball bearing version available","Precisely fitted pair of gears placed in the housing of the flow meter. The rotation of the measuring element is detected by a contactless sensor system and converted into digital signals.","A metering unit containing a gear based flowmeter combined with a flow-regulating and dispensing valve is ideal for an accurate dispensing or filling of larger quantities of fluids."]}]'::jsonb, false),
('gp-302', 'GP 302', '2025-12-23', null, 'The GP- 302 series is a mid-level solvent free gear metering and mixing system used to handle low to medium high viscosity multi component media such as epoxy resins polyurethanes or silicones with a volumetric mixing ratio of between 100:100 and 100:2. Special configurations to process high viscosity media are also available. This system can be customized for individual customer needs and integrated without difficulty into automation cells.', null, null, true),
('gp-401-apd-cf-versa', 'GP 401 APD & CF Versa', '2025-12-23', null, 'Versatile & flexible for demanding workspaces High metering accuracy due to short distance from metering to dispensing Highly comfortable operation with flexible boom and balancer support. Different options & features are configurable to meet requirements', '{"src":"/products/csm_Conti-Flow-Versa_59010974af-1.png","alt":"Device for industrial dispensing"}'::jsonb, null, true),
('gp-401-tpd', 'GP 401 TPD', '2025-12-23', null, 'The TOOL-MIX 401 GP has been specifically designed for handling pasty two component materials, including polyurethanes and epoxy resins, as well as for successfully processing micro-ball filled materials. It is especially suitable for use in such applications as model making in the automotive, aeronautical and shipbuilding industries as well as sealing and adhesive dispensing.', '{"src":"/products/tool-mix-401-gp.jpg","alt":"GP 401 TPD Device for industrial dispensing"}'::jsonb, '[{"heading":"The TOOL-MIX 401 GP is characterized by","items":["lower material degradation than similar systems due to the optimized construction of the gear pumps.","careful construction for gentle material feeding","minimum maintenance required, due to just a single pump for each component","The system is controlled by a high capacity metering computer.","Viscosity range (mPa s) 50,000 to 1,000,000","Mixing ratio (volumetric) 100:100 to 100:10","Flow rate (l/min) 0,7 to 5,0 depending on metering ratio and material properties"]}]'::jsonb, false),
('gp-301', 'GP-301', '2026-05-04', 'Accurate, Continuous Flow and Shot Dispensing', 'Solvent-free gear metering and mixing system used to handle low to medium viscosity multi-component media such as epoxy resins, polyurethanes, or silicones.', '{"src":"/products/GP-301-for-bulk-feed.jpg","alt":"GP-301"}'::jsonb, '[{"heading":"Engineered for Performance","items":["A wide selection of pump types and sizes is independently driven to dial in your ratio","Flow rates from 2 cc/sec to 100 cc/sec (1.5 gal/min), depending on pump selection","Color Touch screen HMI interface displays ratios, flow rates, and other process functions","Continuous or shot dispensing for silicones, polyurethanes, or epoxies; filled and unfilled","progressive cavity and magnetic drive pumps,","Static or Dynamic mixing head","Process Automation"]},{"heading":"Simple Interface Software is:","items":["Easy to Learn and Operate","Calibrate Mix Ratios in a few Easy Steps","Handles all your Process Control Needs","Ratio monitoring system uses independent meters to ensure ratio accuracy","Two levels of password access protect critical process settings"]},{"heading":"GP-301 Direct Dispense","items":["Motionless mixers are used","Processing materials that do not separate","Feeding a mixed material stream to a continuous process (such as laminator, coating line or filament winder)","Shot duration is from two seconds to infinite Optional photo eye controlled.","Material ratios are from 1:1 to 5:1","Process requires only limited temperature control"]},{"heading":"GP-302 Re-circulation System","items":["Motionless mixers are used","A light-weight mixing head is required","Closed loop ratio control is desired","Discontinuous shot or bonding applications are used","Chemistries may separate or stratify","Optional closed loop ratio control available"]},{"heading":"GP-303 Feed/Reservoir System","items":["Stainless steel or mild steel bottom outlet tank construction","Vacuum or bulk feed options","Stands","5 gal (20 l)","10 gal (40 l)","55-gal (200 l) drum feed systems"]},{"heading":"Technical Specifications and System Options","items":["Agitators","Printer","Pressure Tanks","Air Dryer","Mass Flowmeter for Ratio Monitoring","Vacuum Pump","Process Temperature Control","Auto-Refill","Sight Gauge","Desiccant","Audible Alarm","Gear Flowmeter for Ratio Monitoring","Third Component Injection"]},{"heading":"Plural Component Rotary Pump Metering Mix and Dispense Unit:","paragraphs":["Engineered for Performance A wide selection of pump types and sizes are independently driven to dial in your ratio Flow rates from 2 cc/sec to 100 cc/sec (1.5 gal/min) depending on pump selection Color Touch screen HMI interface displays ratios, flow rates and other process functions Continuous or shot dispensing for silicones, polyurethanes or epoxies; filled and unfilled Additional options include: progressive cavity and magnetic drive pumps, Static or Dynamic mixing head Process Automation"]},{"heading":"Simple Interface Software is:","paragraphs":["Easy to Learn and Operate Calibrate Mix Ratios in a few Easy Steps Handles all your Process Control Needs Ratio monitoring system uses independent meters to ensure ratio accuracy Two levels of password access protect critical process settings"]},{"heading":"Customize the GP-301 to Your Manufacturing Process","paragraphs":["GP-301 Direct Dispense Use the process flow configuration when: Motionless mixers are used Processing materials that do not separate Feeding a mixed material stream to a continuous process (such as a laminator, coating line, or filament winder) Shot duration is from two seconds to infinite Optional photo eye controlled. Material ratios are from 1:1 to 5:1 Process requires only limited temperature control GP-302 Re-circulation System Use the Re-circulation System configuration when: Motionless mixers are used A light-weight mixing head is required Closed-loop ratio control is desired Discontinuous shot or bonding applications are used Chemistries may separate or stratify Optional closed-loop ratio control available GP-303 Feed/Reservoir System After selecting the correct metering pump and mixing head, choose your feed system. All systems are available with: Stainless steel or mild steel bottom outlet tank construction Vacuum or bulk feed options Stands Chemistry dictates the construction materials and the process aids, such as heat and agitation. The application and dispense volumes will lead to reservoir size and refilling options. A range of reservoir sizes is available: 5 gal (20 l) 10 gal (40 l) 55-gal (200 l) drum feed systems"]},{"heading":"Technical Specifications and System Options","paragraphs":["Options to create your own meter mix dispense system. Agitators Printer Pressure Tanks Air Dryer Mass Flowmeter for Ratio Monitoring Vacuum Pump Process Temperature Control Auto-Refill Sight Gauge Desiccant Audible Alarm Gear Flowmeter for Ratio Monitoring Third Component Injection"]}]'::jsonb, false),
('gp-703', 'GP-703', '2025-12-23', 'Eldo Mix', 'The ELDO-MIX gel coat systems have been especiallydeveloped for processing highly thixotropic materials ontothe untreated surfaces of rotor blades. By the use of gearmetering pumps\ which are also suitable for abrasive fillersand magnetically coupled axial piston pumps for the Bcomponent; output rates of up to 5 l/min can be achieved.The material supply of the mobile system is carried out frommaterial pressure vessels that are installed on the chassis. Not only can materials with viscosities up to the flow limit beapplied with this gel coat system but also the mixing ratiosare adjustable within a wide range.', '{"src":"/products/Gel_Coat-2C.jpg","alt":"Eldo mix on portable dolly"}'::jsonb, null, true),
('graco-8900', 'Graco 8900', '2025-12-23', 'Precise, Positive Displacement with Double-Acting Cylinders', 'The 8900 Proportioner uses fluid inlet pressure to continuously reciprocate two connected cylinders. This fluid pressure is usually provided by two pumps which supply consistent pressure to the proportioner cylinders. As the major volume cylinder (base) and minor volume cylinder (catalyst) reciprocate, they positively displace the two material components on ratio to the outlet ports. Specially-sized hoses connect the proportioner to a choice of mixers to ensure ratio accuracy. Static mixers are incorporated into the system to deliver a homogeneous mix of base and catalyst.', '{"src":"/products/graco-8900cui482.gif","alt":"Graco 8900"}'::jsonb, '[{"heading":"Graco 8900 Features:","items":["Dependable, production-proven operation","Rugged, reliable heavy-duty components","Fixed or adjustable ratio versatility","Continuous, \"on-demand\" or adjustable shot-size dispensing","Modular system configurations for customizing to suit your needs"]},{"heading":"Graco 8900 Key Applications:","items":["Polysulfide sealants for the aerospace industry","Epoxies for product assembly"]},{"heading":"Graco 8900 Key Materials:","items":["Polysulfide","Silicone","Urethane","Epoxy"]}]'::jsonb, false),
('graco-hydra-cat', 'Graco Hydra Cat', '2025-12-07', 'Accurately proportion plural-component materials', 'Fixed Ratio Hydra-Cat proportioners accurately pump plural-component materials by powering two or three positive displacement pumps from a common air motor. This assures that the stroke rate and stroke length of all pump lowers are identical, providing constant proportioning. Models with two identically-sized lowers provide balanced pumping forces which prevents premature packing wear. Models with three pump lowers and cylinders of various sizes can be selected to provide a wide variety of mix ratios.', '{"src":"/products/hydracattusv92.gif","alt":"Graco Hydra Cat connected to storage devices ready for use"}'::jsonb, '[{"heading":"Graco Hydra-Cat Features:","items":["Severe Duty lowers for wear-resistance and durability","Multiple pump lower configurations achieve a wide variety of mix ratios","Two-pump lower offers a consistent 1:1 mix ratio","Three-pump lower provides mix ratios above 1:1 for balanced pumping","Teflon packings are standard on Hydra-Cat lowers"]},{"heading":"Graco Hydra-Cat Key Applications:","items":["Farm and construction equipment","Truck and bus","General metal fabrication","Foam and elastomerics","Sealants and adhesives"]},{"heading":"Graco Hydra-Cat Key Materials:","items":["Epoxies","Polyurethanes","Waterbornes","Acid-catalyzed wood finishing materials","Stains, lacquers, and varnishes"]}]'::jsonb, false),
('handheld-dispensing-valves', 'Handheld Dispensing Valves', '2026-05-14', 'For manual dispensing of grease and oil', 'The handheld dispensing valve draws on the tried and tested dispensing valves made by KIRKCO. Having been developed specifically for use in manual applications, the handheld dispensing valve is an excellent performer in applications where grease or oil is dispensed continuously by hand. The shot volume is regulated by adjusting the valve opening time and material pressure. Additional components for measurement and control are available. The handheld dispensing valve is mounted vertically and allows access even to hard-to-reach areas. Due to its user-friendly design, the handling is simple and quick. For volumetric dispensing and dot application, KIRKCO recommends the handheld metering valve.', '{"src":"/products/Handheld_Dispensing_03_24_2026.jpg","alt":"Handheld Dispensing Valves"}'::jsonb, '[{"heading":"Handheld Dispensing Valve Features","items":["Type: LW2.5 (based on the dispensing valve)","Only available as a complete assembly","Pneumatic or electronic version","For vertical mounting on a balancer or similar","Ergonomic handle"]}]'::jsonb, false),
('high-pressure-impingement-mixing-valve', 'High Pressure Impingement Mixing Valve', '2025-12-26', 'Impingement Mixing Valves for Urethane Foam & Elastomer: Enhancing Productivity', 'Welcome to Kirkco, your trusted partner for advanced impingement mixing valves designed to elevate productivity in both filled and unfilled polyurethane applications. Our high-performance, high-pressure mixing heads stand at the forefront of foam processing units, featuring a precision tight-tolerance plunger design that sets industry standards.', '{"src":"/products/800_800_image_291978_30907397_78805a221a988e79ef3f42d7c5bfd418.png","alt":"High Pressure impingement mixing valve"}'::jsonb, '[{"heading":"How it Works:","paragraphs":["The High-Pressure Impingement Mixing Valve operates with meticulous precision, ensuring the seamless blending of materials in both filled and unfilled polyurethane applications. During the dispensing cycle, our valve utilizes a recirculation mode, where materials flow through control orifices and recirculation grooves on each side of a precision plunger. This innovative design allows for optimal mixing efficiency before the materials impinge at pressures of up to 3,500 psi, resulting in a smooth and consistent pour into open and closed molds, enhancing the overall quality of your end products."]},{"heading":"Applications of Use:","paragraphs":["Our High-Pressure Impingement Mixing Valve finds its prowess in a diverse range of applications, making it a versatile and indispensable tool in the realm of polyurethane processing.."],"items":["Closed Mold Applications: The valve excels in closed mold applications, providing reliable and cost-effective processing for automotive parts, industrial components, and more.","Open Mold Applications: Tailored for open mold applications, our mixing valve facilitates precise pouring for continuous and discontinuous panel applications, ensuring efficiency in diverse manufacturing processes.","Spray Applications: The valve''s design is optimized for spray applications, making it an ideal choice for industries requiring a high degree of precision in coating and insulation processes.","Continuous Sandwich Panel Applications: Specifically engineered for continuous sandwich panel applications, our mixing valve contributes to the production of high-quality panels used in construction and other industries.","Filler/Powder Incorporation: The valve''s versatility extends to filler/powder incorporation, allowing for efficient blending of raw materials to meet the specific requirements of your formulations."]},{"heading":"Benefits of High-Pressure Impingement Mixing Valve:","items":["Enhanced Mixing Efficiency: The precision design ensures thorough impingement, leading to improved mixing efficiency and superior product quality.","Cost Savings: By eliminating the need for cleaning solvents and reducing waste, our mixing valve contributes to significant cost savings in your production processes.","Fast-Reaction Formulations: The valve''s capabilities enable the use of fast-reacting formulations, reducing production cycle times and increasing overall productivity."]},{"heading":"High-Pressure Foam Mix Heads for Reliable, Cost-Effective Polyurethane Processing:","paragraphs":["KIRKCO L-style and straight polyurethane foam mixing heads are designed for high-pressure impingement mixing, offering long life across a wide range of open mold and closed mold applications."]},{"heading":"Straight Type Mixing Head:","paragraphs":["During a recirculation mode, materials flow through control orifices and recirculation grooves on each side of a precision plunger before returning to the machine tanks. When a dispense cycle is initiated, the plunger, actuated by a double-acting cylinder, retracts, allowing both materials to impinge at pressures up to 3,500 psi (ideal for closed mold applications)."]},{"heading":"Straight-Style Mix Head Features:","items":["Ideal for continuous and discontinuous panel applications.","Compact","Economical"]},{"heading":"Injector Styles:","paragraphs":["Conical Style injectors for rigid and flexible foam applications, including refrigerators, walk-in coolers, furniture, and automotive seat cushions. Choose from a wide range of orifice and needle sizes for optimal mixing and shot control.","Diesel Style injectors for hard-to-mix polyurethane foam applications like steering wheels and acoustical foams. Select from various sizes and spring-adjustment or pin-adjusted holders.","Pneumatically controlled injectors are available for setpoint control or remote adjustment of shot pressures. Let our process experts help you select the correct model and combination of injectors for your application."]},{"heading":"L-Style Mix Head Features:","items":["Special nozzle lengths available.","Double L mix heads with two pour pistons for seating applications.","High-strength materials and seals for maximum durability.","Separate cleanout hydraulics from the chemical block to minimize oil contamination.","Laminar output flow for splash-free operation with open molds.","200,000 shots, 1-year warranty.","Low-cost repairs and seal changes available.","Optimum shot control.","Variety of injector styles and sizes to fit your application.","Adjustable cleanout piston stroke improves mixing efficiency (standard on every mix head).","Double cleanout piston seals for longer life.","Optional recirculating color groove."]}]'::jsonb, false),
('high-pressure-pumps', 'High Pressure Pumps', '2026-05-14', 'High-Pressure Lubrication Pumps for Grease, Oil & Industrial Fluid Delivery', 'Kirkco high-pressure pumps are engineered to reliably deliver lubricants — including greases, oils, and other viscous fluids — at elevated pressures required for feeding metering systems, dispensing valves, or centralized lubrication networks. These pumps are ideal for industrial environments where consistent high pressure, repeatable feed rates, and robust service life are essential.', '{"src":"/products/KC_BoosterMix_HMI-1.jpg","alt":"High Pressure Pumps"}'::jsonb, '[{"heading":"Key Features:","items":["Pneumatic double-acting piston design for heavy service","Delivers high pressure suitable for complex lubrication networks","Handles medium to high viscosity greases and oils","Minimal pulsation with consistent feed to downstream valves","Durable construction for industrial use"]},{"heading":"Applications:","items":["Centralized lubrication stations","High-pressure metering valve feed systems","Heavy equipment lubrication loops"]},{"heading":"Key Features:","items":["Air-operated for facility safety and robust operation","Smooth output at high pressure for viscous lubricants","Self-priming and dry-run capable","Compatible with a wide range of greases and oils","Maintenance-friendly design"]},{"heading":"Applications:","items":["High-pressure grease feed to valves","Lubricant transport in machine tool and press applications","Automated lubrication delivery systems"]},{"heading":"Key Features:","items":["High-pressure delivery directly from bulk containers","Pneumatic or hydraulic operation options","Uniform feeding avoids air entrainment","Suitable for extended duty cycles","Works with metering and dispensing downstream"]},{"heading":"Applications:","items":["Drum-mounted high-pressure lubricant feed","Bulk container supply for automated lubrication","Centralized feed into metering systems"]}]'::jsonb, false),
('high-speed-valves', 'High Speed Dispensing Valves', '2026-05-14', 'Contactless greasing in automated processes', 'The high-speed valve is used in contactless (from a distance) applications of grease and oil where stringing must be avoided. The compact design of the valve enables an effortless and effective greasing of narrow and hard-to-reach spaces. The dot application takes place in the longitudinal direction of the nozzle with a perfect material cut off after each shot. With short cycle times, this valve is ideal for integration into highly efficient processes. Thanks to an innovative nozzle with a self-cleaning effect and an integrated filter, the high speed valve delivers a perfectly clean application everytime. An integrated heating element keeps the material properties at their optimum, ensuring high process stability and reproducibility.', '{"src":"/products/High-Speed-Valve_03_24_2026.jpg","alt":"High Speed Dispensing Valves"}'::jsonb, '[{"heading":"High-Speed Dispensing Valve Features","items":["Shot Application","Nozzle size ⌀ 0.21 – 0.81 mm","Input pressure max. 70 bar","24V DC solenoid valve for maximum shot frequency of 100 Hz","Integrated 230 V AC / 155 W heating with a temperature sensor PT100","Option - 5m cable for heating","Option - Light barrier for shot detection"]}]'::jsonb, false),
('i-mix', 'I MIX', '2025-12-10', 'Polyurethane Processing Equipment', 'Low Pressure foaming machines I Mix Series has great flexibility for small to medium productions, and can make use of multiple mixing heads, with flow rates from 5 to 5000 gr / sec. Boom mounted control panel.', '{"src":"/products/I_MIX_LOW_PRESSURE_FOAMING_MACHINE_MP__26829.webp","alt":"Low Pressure Foaming Machine for polyurethane foam"}'::jsonb, null, true),
('icf-integral-compact-filter-spray-system', 'ICF – Integral Compact Filter Spray System', '2025-12-26', 'Automated spray systems needing frequent filter changes.', 'The Integral Compact Filter (ICF) stainless steel filter booth is designed for automatic powder coating and manual coating. By changing the powder and filter trolleys, color changes can be carried out. It stands out for its stable and robust construction. The stainless steel floor is accessible.', null, null, true);